package net.civeira.phylax.feature.observe.observedalert.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.feature.observe.observedalert.domain.ObservedAlert;
import net.civeira.phylax.feature.observe.observedalert.domain.gateway.ObservedAlertCursor;
import net.civeira.phylax.feature.observe.observedalert.domain.gateway.ObservedAlertFilter;

class ObservedAlertSlider extends Slider<ObservedAlert> {

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedAlertCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final ObservedAlertFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<ObservedAlertFilter, ObservedAlertCursor, Iterator<ObservedAlert>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  ObservedAlertSlider(final Iterator<ObservedAlert> multi, final int limit,
      final BiFunction<ObservedAlertFilter, ObservedAlertCursor, Iterator<ObservedAlert>> gateway,
      final ObservedAlertFilter filter, final ObservedAlertCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param observedAlerts
   * @param limit
   * @return
   */
  @Override
  public Iterator<ObservedAlert> next(List<ObservedAlert> observedAlerts, int limit) {
    ObservedAlert last = observedAlerts.get(observedAlerts.size() - 1);
    ObservedAlertCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
